package local.luma.music;
import android.content.Context;
import org.json.*;
import java.io.IOException;
import java.util.*;

final class CollectionStore {
 static JSONArray load(Context c)throws Exception{JSONArray records=Store.load(c).optJSONArray("collectionRecords");return records==null?new JSONArray():records;}
 static JSONArray merge(Context c,JSONArray incoming)throws Exception{synchronized(Store.class){JSONObject data=Store.load(c);JSONArray old=data.optJSONArray("collectionRecords");if(old==null)old=new JSONArray();JSONArray next=PlaylistStore.merge(old,incoming);if(!old.toString().equals(next.toString())){data.put("collectionRecords",next);Store.save(c,data);}return next;}}
 private static JSONObject tick(JSONObject record,String actor)throws Exception{JSONObject clock=record.optJSONObject("clock");if(clock==null)clock=new JSONObject();clock.put(actor,clock.optLong(actor)+1);return record.put("clock",clock).put("editId",UUID.randomUUID().toString());}
 static void prune(JSONObject data,Set<String> removed)throws Exception{JSONArray records=data.optJSONArray("collectionRecords"),tracks=data.getJSONArray("tracks");if(records==null)return;String actor=data.optString("collectionActor");if(actor.isEmpty()){actor="collections-"+UUID.randomUUID();data.put("collectionActor",actor);}for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);if(r.optBoolean("deleted"))continue;JSONObject meta;try{meta=new JSONObject(r.optString("description"));}catch(JSONException e){continue;}String type=meta.optString("type"),artist=meta.isNull("artist")?null:meta.optString("artist",null);boolean exists=false;for(int n=0;n<tracks.length();n++){JSONObject t=tracks.getJSONObject(n);if(t.optString(type).equals(r.optString("name"))&&(!type.equals("album")||artist==null||t.optString("artist").equals(artist))){exists=true;break;}}JSONArray old=r.getJSONArray("tracks"),kept=new JSONArray();for(int n=0;n<old.length();n++)if(!removed.contains(old.getString(n)))kept.put(old.getString(n));if(!exists||kept.length()!=old.length()){r.put("tracks",kept).put("deleted",!exists);if(!exists)r.put("image","");tick(r,actor);}}}
 static JSONObject edit(Context c,JSONObject args)throws Exception{synchronized(Store.class){
  String type=args.getString("type"),key=args.getString("key"),name=args.optString("name").trim(),artist=args.isNull("artist")?null:args.optString("artist",null);if(!type.equals("album")&&!type.equals("artist"))throw new IOException("Некорректная подборка");if(name.isEmpty())throw new IOException("Введите название");if(name.length()>100)name=name.substring(0,100);if(args.has("image"))TrackDetails.clean(new JSONObject().put("customCover",args.getString("image")));
  JSONObject data=Store.load(c);JSONArray tracks=data.getJSONArray("tracks"),old=data.optJSONArray("collectionRecords");if(old==null)old=new JSONArray();JSONArray ids=new JSONArray();Set<String> selected=new HashSet<>();
  for(int i=0;i<tracks.length();i++){JSONObject t=tracks.getJSONObject(i);if(t.optString(type).equals(key)&&(!type.equals("album")||artist==null||t.optString("artist").equals(artist))){ids.put(t.getString("id"));selected.add(t.getString("id"));}}
  if(ids.length()==0)throw new IOException("Подборка не найдена");
  for(int i=0;i<tracks.length();i++){JSONObject t=tracks.getJSONObject(i);if(!name.equals(key)&&t.optString(type).equals(name)&&(!type.equals("album")||artist==null||t.optString("artist").equals(artist)))throw new IOException("Такое название уже есть. Выберите другое.");}
  JSONObject record=null;for(int i=0;i<old.length();i++){JSONObject r=old.getJSONObject(i);try{JSONObject meta=new JSONObject(r.optString("description"));String scope=meta.isNull("artist")?null:meta.optString("artist",null);if(!r.optBoolean("deleted")&&r.optString("name").equals(key)&&meta.optString("type").equals(type)&&Objects.equals(scope,type.equals("album")?artist:null)){record=new JSONObject(r.toString());break;}}catch(JSONException ignored){}}
  if(record==null)record=new JSONObject().put("id","collection-"+UUID.randomUUID()).put("image","").put("clock",new JSONObject());
  String actor=data.optString("collectionActor");if(actor.isEmpty()){actor="collections-"+UUID.randomUUID();data.put("collectionActor",actor);}
  record.put("name",name).put("description",new JSONObject().put("type",type).put("artist",type.equals("album")&&artist!=null?artist:JSONObject.NULL).toString()).put("tracks",ids).put("deleted",false);if(args.has("image"))record.put("image",args.getString("image"));JSONArray incoming=new JSONArray().put(tick(record,actor));
  if(type.equals("artist")&&!name.equals(key))for(int i=0;i<old.length();i++){JSONObject r=old.getJSONObject(i);try{JSONObject meta=new JSONObject(r.optString("description"));if(!r.optBoolean("deleted")&&meta.optString("type").equals("album")&&meta.optString("artist").equals(key)){JSONObject copy=new JSONObject(r.toString());meta.put("artist",name);copy.put("description",meta.toString());incoming.put(tick(copy,actor));}}catch(JSONException ignored){}}
  JSONArray merged=PlaylistStore.merge(old,incoming);for(int i=0;i<tracks.length();i++){JSONObject t=tracks.getJSONObject(i);if(selected.contains(t.getString("id"))){t.put(type,name);if(type.equals("artist")&&t.optString("albumArtist").equals(key))t.put("albumArtist",name);t.put("detailsUpdatedAt",Math.max(System.currentTimeMillis(),t.optLong("detailsUpdatedAt")+1));}}
  data.put("collectionRecords",merged);Store.save(c,data);return new JSONObject().put("name",name).put("updated",ids.length());
 }}
}
